struct order { long qty; int qty_seen; char *sku; };  /* raw, maybe incomplete */

static int order_valid_for_publish(const struct order *o, struct err *e)
{
    if (!o->qty_seen) return err_set(e, "qty required");
    if (o->qty <= 0)  return err_set(e, "qty must be positive");
    if (!o->sku)      return err_set(e, "sku required");
    return 0;
}
/* gate at the use: */
if (order_valid_for_publish(&o, &e) != 0) return handle(&e);
